//! §11 format-migration matrix: databases written by historical release
//! tags (fixtures generated by scripts/gen_format_fixtures.sh — each tag's
//! own code produces its真实 on-disk layout) must open and query cleanly on
//! the current version, exercising the open-time auto-migration path.
//!
//! Fixtures are copied to a TempDir before opening so the in-tree copies
//! stay pristine (open may write migrated files next to the data).

use motedb::Database;
use std::path::{Path, PathBuf};
use tempfile::TempDir;

fn fixture(tag: &str) -> Option<PathBuf> {
    let p = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/formats")
        .join(tag)
        .join("db.mote");
    p.exists().then_some(p)
}

fn copy_dir(src: &Path, dst: &Path) {
    for entry in std::fs::read_dir(src).unwrap() {
        let entry = entry.unwrap();
        let to = dst.join(entry.file_name());
        if entry.path().is_dir() {
            std::fs::create_dir_all(&to).unwrap();
            copy_dir(&entry.path(), &to);
        } else {
            std::fs::copy(entry.path(), &to).unwrap();
        }
    }
}

/// Canonical expectations — must match scripts/gen_format_fixture.rs.
fn check(tag: &str, db: &Database) {
    let r = db
        .execute("SELECT COUNT(*), MIN(id), MAX(id), SUM(id) FROM mig")
        .unwrap()
        .materialize()
        .unwrap();
    let (_cols, rows) = r.select_rows().unwrap();
    let row = &rows[0];
    assert_eq!(
        row[0],
        motedb::types::Value::Integer(50),
        "{tag}: row count"
    );
    assert_eq!(row[1], motedb::types::Value::Integer(1), "{tag}: min id");
    assert_eq!(row[2], motedb::types::Value::Integer(50), "{tag}: max id");
    assert_eq!(row[3], motedb::types::Value::Integer(1275), "{tag}: sum id");

    // Spot-check values incl. FLOAT/TEXT and an ORDER BY round-trip.
    let r = db
        .execute("SELECT id, f, s FROM mig WHERE id = 42")
        .unwrap()
        .materialize()
        .unwrap();
    let (_cols, rows) = r.select_rows().unwrap();
    assert_eq!(rows.len(), 1, "{tag}: point lookup");
    match &rows[0][1] {
        motedb::types::Value::Float(f) => assert!((f - 21.0).abs() < 1e-9, "{tag}: f={f}"),
        other => panic!("{tag}: expected float, got {:?}", other),
    }
    assert_eq!(
        rows[0][2],
        motedb::types::Value::Text("row42".into()),
        "{tag}: text"
    );

    // Timestamp range through the migrated layout.
    let n = db
        .execute("SELECT COUNT(*) FROM mig WHERE ts >= 1700000042000000")
        .unwrap()
        .materialize()
        .unwrap()
        .select_rows()
        .unwrap()
        .1[0][0]
        .clone();
    assert_eq!(
        n,
        motedb::types::Value::Integer(9),
        "{tag}: ts predicate (ts >= id42)"
    );

    // Vector table is best-effort per era; check when present.
    let has_vec = db.execute("SELECT COUNT(*) FROM mig_vec").is_ok();
    if has_vec {
        let n = db
            .execute("SELECT COUNT(*) FROM mig_vec")
            .unwrap()
            .materialize()
            .unwrap()
            .select_rows()
            .unwrap()
            .1[0][0]
            .clone();
        assert_eq!(n, motedb::types::Value::Integer(20), "{tag}: vector rows");
    }
}

fn matrix_case(tag: &str) {
    let src = match fixture(tag) {
        Some(p) => p,
        None => {
            eprintln!("skipping {tag}: no fixture (run scripts/gen_format_fixtures.sh)");
            return;
        }
    };
    // Copy to temp: opening may write migrated files into the directory.
    let tmp = TempDir::new().unwrap();
    let db_dir = tmp.path().join("db");
    std::fs::create_dir_all(&db_dir).unwrap();
    copy_dir(&src, &db_dir);

    let db = Database::open(&db_dir).unwrap_or_else(|e| panic!("{tag}: open failed: {e}"));
    check(tag, &db);
    drop(db);

    // Reopen after the migrated state persisted — stability of the migration
    // itself (write once, read twice).
    let db = Database::open(&db_dir).expect("{tag}: reopen after migration");
    check(tag, &db);
}

#[test]
fn format_migration_matrix() {
    for tag in ["v0.12.9", "v0.13.0", "v0.14.0", "v0.15.2"] {
        matrix_case(tag);
    }
}
